/// <summary>
/// MCRInventSearch class extension
/// </summary>
[ExtensionOf(classStr(MCRInventSearch))]
final public class NDXMCRInventSearch_cls_Extension
{
    private boolean isSalesItem;

}

Method.Source:
/// <summary>
/// Parm method for isSalesItem
/// </summary>
/// <param name = "_isSalesItem">isSalesItem</param>
/// <returns>isSalesItem</returns>
boolean parmIsSalesItem(boolean _isSalesItem = isSalesItem)
{
    isSalesItem = _isSalesItem;
    return isSalesItem;
}

/// <summary>
/// Overrides buildSearchQuery
/// </summary>
/// <param name = "_mcrSearchText">search text</param>
/// <returns>query</returns>
protected Query buildSearchQuery(MCRSearchText _mcrSearchText)
{
    Query q = next buildSearchQuery(_mcrSearchText);

    if(isSalesItem)
    {
        QueryBuildDataSource qbdsInventDistinctProduct = q.dataSourceTable(tableNum(InventDistinctProduct));

        QueryBuildDataSource qbdsInventTable = qbdsInventDistinctProduct.addDataSource(tableNum(InventTable));
        qbdsInventTable.relations(false);
        qbdsInventTable.joinMode(JoinMode::InnerJoin);
        qbdsInventTable.addLink(fieldNum(InventDistinctProduct, ItemId), fieldNum(InventTable, ItemId));
        qbdsInventTable.addRange(fieldNum(InventTable, KCS_IsSalesItem)).value(queryValue(NoYes::Yes));
    }

    return q;
}
